package model;

public class Rectangle implements Comparable<Rectangle> {
    private double width;
    private double height;

    public Rectangle(double width, double height) { this.width = width; this.height = height; }

    public double getArea() { return width * height; }

    public void setWidth(double width) {
        if (width < 0) throw new IllegalArgumentException("width");
        this.width = width;
    }

    @Override public String toString() { return "Rectangle{width=" + width + ", height=" + height + "}"; }

    @Override public int compareTo(Rectangle o) { return Double.compare(getArea(), o.getArea()); }
}

